import{c as o,S as a,j as r,m as t}from"./chunks/framework.VsSDrsS3.js";const h=JSON.parse('{"title":"微信小程序 WebView 缓存 & 常见坑","description":"","frontmatter":{},"headers":[],"relativePath":"knowledge/wechat/webview-cache.md","filePath":"knowledge/wechat/webview-cache.md","lastUpdated":1780046787000}'),i={name:"knowledge/wechat/webview-cache.md"};function n(s,e,c,l,d,g){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="微信小程序-webview-缓存-常见坑" tabindex="-1">微信小程序 WebView 缓存 &amp; 常见坑 <a class="header-anchor" href="#微信小程序-webview-缓存-常见坑" aria-label="Permalink to “微信小程序 WebView 缓存 &amp; 常见坑”">​</a></h1><h2 id="webview-缓存问题" tabindex="-1">WebView 缓存问题 <a class="header-anchor" href="#webview-缓存问题" aria-label="Permalink to “WebView 缓存问题”">​</a></h2><p><strong>问题：</strong> 小程序 web-view 嵌入的 H5 页面更新后，用户看到的仍是旧版本。</p><p><strong>原因：</strong> web-view 组件会缓存已加载的 H5 资源（HTML/JS/CSS）。</p><p><strong>解决方案（按推荐度排序）：</strong></p><ol><li><strong>src 加时间戳：</strong> <code>src=&quot;https://xxx.com/page?v=${Date.now()}&quot;</code> — 最简单但 ⚠️ <strong>完全破坏 CDN 缓存</strong>，每次加载都回源。<code>Cache-Control: no-cache</code> 是更好的折衷</li><li><strong>服务端配置 Cache-Control：</strong> <code>Cache-Control: no-cache</code> 或 <code>max-age=0</code></li><li><strong>重启小程序：</strong> <code>wx.restartMiniProgram()</code> — 核武器，慎用</li><li><strong>监听版本更新：</strong> 使用 <code>updateManager</code> API 检测新版小程序，提示用户重启</li></ol><h3 id="webview-其他坑" tabindex="-1">WebView 其他坑 <a class="header-anchor" href="#webview-其他坑" aria-label="Permalink to “WebView 其他坑”">​</a></h3><ul><li><strong>动态修改 src 产生 history：</strong> 每次修改 <code>src</code> 会新增一条页面历史，需按多次返回。解决：使用 <code>wx.redirectTo</code> 替代 <code>wx.navigateTo</code></li><li><strong>一个页面只能有一个 web-view：</strong> 多次插入会报错</li><li><strong>postMessage 收不到：</strong> <code>wx.miniProgram.postMessage</code> 是延迟投递（在后退/销毁/分享时才触发），不是实时通信。如需实时通信，使用 H5 的 <code>window.postMessage</code> 但需注意跨域限制</li><li><strong>H5 跳转小程序：</strong> 使用 <code>wx-open-launch-weapp</code> 开放标签，需在公众号后台配置 JS 安全域名</li></ul><h2 id="小程序视频播放问题" tabindex="-1">小程序视频播放问题 <a class="header-anchor" href="#小程序视频播放问题" aria-label="Permalink to “小程序视频播放问题”">​</a></h2><p><strong>iOS 播放视频常见问题：</strong></p><ul><li><strong>黑屏/MEDIA_ERR_NETWORK：</strong> 可能是服务端不支持 Range 请求（Accept-Ranges），iOS Safari 强制要求</li><li><strong>无声音：</strong> Android 和开发者工具正常，iOS 无声，检查音频编码格式（AAC 兼容性最好）</li><li><strong>MP4 格式：</strong> iOS 需要 H.264 编码 + AAC 音频，不能是 H.265/HEVC</li></ul><p>（视频缩略图通用方案见 <a href="./../frontend/file-processing">前端文件处理 - 视频首帧缩略图</a>）</p>',12)])])}const p=o(i,[["render",n]]);export{h as __pageData,p as default};
